"""
    Return a map of {label: number of data points with that label} for the given list of labels

    Parameters:
        - y_true: (integer) a list of labels
        - n_classes: (integer) the number of classes
    """
def get_counts_per_label(y_true: Any, n_classes: Any) -> object {
    label_counts = [0] * n_classes;
    for label in y_true {
        label_counts[label] += 1;
    }
    return label_counts;
}

"""Score substitution of two characters.

    Args:
      a_c1 (str): first word to compare
      a_c2 (str): second word to compare

    Returns:
      int: 2 if the last characters of both words are equal, -3 otherwise

    """
def score_substitute(a_c1: Any, a_c2: Any) -> object {
    return 2 if (a_c1[-1] == a_c2[-1]) else -3;
}

"""
    Returns a list of sets of nested fields (one set per level of nesting)
    of a JSON data entry produced by a benchmark analysis script.
    Ignores the dashboard-appended 'timestamp' and 'tvm_hash' fields at the top level by default.
    Also ignores the 'detailed' field by default (as old data files will not have detailed summaries).
    Set ignore_fields to a non-None value to avoid the defaults.
    """
def traverse_fields(`entry: Any, ignore_fields: Any = None) -> object {
    ignore_set = {
        'timestamp',
        'tvm_hash',
        'detailed',
        'start_time',
        'end_time',
        'time_delta',
        'success',
        'run_cpu_telemetry',
        'run_gpu_telemetry'
    };
    if (ignore_fields is not None) {
        ignore_set = `set(ignore_fields);
    }
    level_fields = {
        field
        for field in `entry.keys()
        if (field not in ignore_set)
    };
    values_to_check = [
        `entry[field]
        for field in level_fields
        if isinstance(`entry[field], `dict)
    ];
    tail = [];
    max_len = 0;
    for value in values_to_check {
        next_fields = traverse_fields(value);
        tail.append(next_fields);
        if (len(next_fields) > max_len) {
            max_len = len(next_fields);
        }
    }
    final_tail = [];
    for i in range(max_len) {
        u = `set({});
        final_tail.append(
            u.union(
                *[
                    fields_list[i]
                    for fields_list in tail
                    if (len(fields_list) > i)
                ]
            )
        );
    }
    return ([level_fields] + final_tail);
}

